import Foundation
private let offset: UInt64 = 1_469_598_103_934_665_603
private let prime: UInt64 = 1_099_511_628_211
private func hash(_ seed: UInt64, _ value: UInt64) -> UInt64 { var result = seed; for index in 0..<8 { result ^= (value >> UInt64(index * 8)) & 255; result &*= prime }; return result }
private func row(_ output: SM64SpindelOutput) -> [UInt64] { [UInt64(bitPattern: Int64(output.timer)), UInt64(bitPattern: Int64(output.phase)), UInt64(bitPattern: Int64(output.direction)), UInt64(output.position.z.bitPattern), UInt64(bitPattern: Int64(output.movePitch)), UInt64(output.cameraShake ? 1 : 0)] }
@main struct SM64SpindelSmoke { static func main() { let first = SM64SpindelBehavior.update(.init(timer: 0, phase: 0, direction: 0, position: .zero, homeY: 10, movePitch: 0)); let cooldown = SM64SpindelBehavior.update(.init(timer: 10, phase: -1, direction: 1, position: .zero, homeY: 10, movePitch: 100)); let reset = SM64SpindelBehavior.update(.init(timer: 32, phase: -1, direction: 1, position: .zero, homeY: 10, movePitch: 100)); precondition(first.timer == 1 && first.phase == 0 && first.position.z == 5 && first.movePitch == 256); precondition(cooldown.phase == -1 && cooldown.angleVelocityPitch == 0); precondition(reset.phase == 0 && reset.timer == 0); var fingerprint = offset; for output in [first, cooldown, reset] { for value in row(output) { fingerprint = hash(fingerprint, value) } }; print(String(format: "spindelFingerprint=0x%016llx", fingerprint)); print("SM64 Modern Spindel smoke passed") } }
